public enum WireDecoder {
    public static func decodeShape(_ kind: String, data: Data) throws {
        switch kind {

        case "Id": _ = try JSONDecoder().decode(Id.self, from: data)

        case "Instant": _ = try JSONDecoder().decode(Instant.self, from: data)

        case "TimeZone": _ = try JSONDecoder().decode(ZoneName.self, from: data)

        case "Hash": _ = try JSONDecoder().decode(Hash.self, from: data)

        case "Location": _ = try JSONDecoder().decode(Location.self, from: data)

        case "DeviceIdentity": _ = try JSONDecoder().decode(DeviceIdentity.self, from: data)

        case "DeviceState": _ = try JSONDecoder().decode(DeviceState.self, from: data)

        case "Capture": _ = try JSONDecoder().decode(Capture.self, from: data)

        case "ManifestEntry": _ = try JSONDecoder().decode(ManifestEntry.self, from: data)

        case "Gap": _ = try JSONDecoder().decode(Gap.self, from: data)

        case "BeginSync": _ = try JSONDecoder().decode(BeginSync.self, from: data)

        case "Snapshot": _ = try JSONDecoder().decode(Snapshot.self, from: data)

        case "Manifest": _ = try JSONDecoder().decode(Manifest.self, from: data)

        case "GrantItem": _ = try JSONDecoder().decode(GrantItem.self, from: data)

        case "GrantRequest": _ = try JSONDecoder().decode(GrantRequest.self, from: data)

        case "UploadGrant": _ = try JSONDecoder().decode(UploadGrant.self, from: data)

        case "UploadGrants": _ = try JSONDecoder().decode(UploadGrants.self, from: data)

        case "CompleteSync": _ = try JSONDecoder().decode(CompleteSync.self, from: data)

        case "Receipt": _ = try JSONDecoder().decode(Receipt.self, from: data)

        case "SyncRequestInput": _ = try JSONDecoder().decode(SyncRequestInput.self, from: data)

        case "SyncRequest": _ = try JSONDecoder().decode(SyncRequest.self, from: data)

        case "Command": _ = try JSONDecoder().decode(Command.self, from: data)

        case "Acknowledgement": _ = try JSONDecoder().decode(Acknowledgement.self, from: data)

        case "Configuration": _ = try JSONDecoder().decode(Configuration.self, from: data)

        case "Evidence": _ = try JSONDecoder().decode(Evidence.self, from: data)

        case "Observation": _ = try JSONDecoder().decode(CaptureObservation.self, from: data)

        case "Moment": _ = try JSONDecoder().decode(Moment.self, from: data)

        case "Coverage": _ = try JSONDecoder().decode(Coverage.self, from: data)

        case "Recap": _ = try JSONDecoder().decode(Recap.self, from: data)

        case "EditInput": _ = try JSONDecoder().decode(EditInput.self, from: data)

        case "Reflection": _ = try JSONDecoder().decode(Reflection.self, from: data)

        case "Correction": _ = try JSONDecoder().decode(Correction.self, from: data)

        case "Day": _ = try JSONDecoder().decode(Day.self, from: data)

        case "CalendarOccurrence": _ = try JSONDecoder().decode(CalendarOccurrence.self, from: data)

        case "CalendarSnapshot": _ = try JSONDecoder().decode(CalendarSnapshot.self, from: data)

        case "CalendarPage": _ = try JSONDecoder().decode(CalendarPage.self, from: data)

        case "CalendarComplete": _ = try JSONDecoder().decode(CalendarComplete.self, from: data)

        case "CalendarBundle": _ = try JSONDecoder().decode(CalendarBundle.self, from: data)

        case "DeletionJob": _ = try JSONDecoder().decode(DeletionJob.self, from: data)

        case "Error": _ = try JSONDecoder().decode(APIError.self, from: data)

        case "Profile": _ = try JSONDecoder().decode(Profile.self, from: data)

        case "Preferences": _ = try JSONDecoder().decode(Preferences.self, from: data)

        case "ClaimInput": _ = try JSONDecoder().decode(ClaimInput.self, from: data)

        case "ClaimProof": _ = try JSONDecoder().decode(ClaimProof.self, from: data)

        case "Claim": _ = try JSONDecoder().decode(Claim.self, from: data)

        case "PushInstallation": _ = try JSONDecoder().decode(PushInstallation.self, from: data)

        case "ReadGrant": _ = try JSONDecoder().decode(ReadGrant.self, from: data)

        case "DeviceDetail": _ = try JSONDecoder().decode(DeviceDetail.self, from: data)

        case "Days": _ = try JSONDecoder().decode(Days.self, from: data)

        case "Devices": _ = try JSONDecoder().decode(Devices.self, from: data)

        case "Moments": _ = try JSONDecoder().decode(Moments.self, from: data)

        case "Transition": _ = try JSONDecoder().decode(Transition.self, from: data)

        default: throw ContractFailure.invalid(kind)
        }
    }
}
